options.device\_id = 0;

options.arena\_extend\_strategy = 0;

options.cudnn\_conv\_algo\_search = OrtCudnnConvAlgoSearch::EXHAUSTIVE;

options.do\_copy\_in\_default\_stream = 1;

session\_options.AppendExecutionProvider\_CUDA(options);

#endif

// 1\. session

ort\_session = new Ort::Session(ort\_env, onnx\_path, session\_options);

Ort::AllocatorWithDefaultOptions allocator;

// 2\. input name & input dims

